"""Derivation and validation for generated Triton MoE calibration artifacts."""

import hashlib
import json
import math
import os
import statistics
from pathlib import Path
from typing import Any


SCHEMA_VERSION = 1
DERIVATION_VERSION = 1
CONFIG_KEYS = (
    "BLOCK_SIZE_M",
    "BLOCK_SIZE_N",
    "BLOCK_SIZE_K",
    "GROUP_SIZE_M",
    "num_warps",
    "num_stages",
)


def canonical_config(config: dict[str, Any]) -> dict[str, int]:
    if set(config) != set(CONFIG_KEYS):
        missing = sorted(set(CONFIG_KEYS) - set(config))
        extra = sorted(set(config) - set(CONFIG_KEYS))
        raise ValueError(f"invalid Triton MoE config keys: missing={missing}, extra={extra}")
    if any(
        isinstance(config[key], bool) or not isinstance(config[key], int)
        for key in CONFIG_KEYS
    ):
        raise ValueError("Triton MoE config values must be integers")
    normalized = {key: config[key] for key in CONFIG_KEYS}
    if any(value <= 0 for value in normalized.values()):
        raise ValueError("Triton MoE config values must be positive")
    return normalized


def config_identity(config: dict[str, Any]) -> str:
    encoded = json.dumps(
        canonical_config(config), sort_keys=True, separators=(",", ":")
    ).encode()
    return hashlib.sha256(encoded).hexdigest()[:16]


def summarize_samples(samples: list[float]) -> dict[str, float | int]:
    if len(samples) < 5:
        raise ValueError("each successful calibration candidate needs at least 5 samples")
    normalized = [float(value) for value in samples]
    if any(not math.isfinite(value) or value <= 0 for value in normalized):
        raise ValueError("calibration samples must be finite and positive")
    median_us = statistics.median(normalized)
    deviations = [abs(value - median_us) for value in normalized]
    return {
        "count": len(normalized),
        "median_us": round(median_us, 6),
        "mad_us": round(statistics.median(deviations), 6),
        "min_us": round(min(normalized), 6),
        "max_us": round(max(normalized), 6),
    }


def make_candidate(
    config: dict[str, Any],
    *,
    samples_us: list[float] | None = None,
    error: str | None = None,
) -> dict[str, Any]:
    normalized = canonical_config(config)
    identity = config_identity(normalized)
    if samples_us is None:
        if not error:
            raise ValueError("failed calibration candidates must retain an error")
        return {
            "identity": identity,
            "config": normalized,
            "status": "error",
            "error": str(error),
        }
    rounded = [round(float(value), 6) for value in samples_us]
    return {
        "identity": identity,
        "config": normalized,
        "status": "ok",
        "samples_us": rounded,
        "summary": summarize_samples(rounded),
    }


def derive_token_selection(candidates: list[dict[str, Any]]) -> dict[str, Any]:
    if not candidates:
        raise ValueError("calibration token bucket has no candidates")
    seen: set[str] = set()
    successful: list[dict[str, Any]] = []
    for candidate in candidates:
        config = canonical_config(candidate["config"])
        identity = config_identity(config)
        if candidate.get("identity") != identity:
            raise ValueError("calibration candidate identity is not derived from its config")
        if identity in seen:
            raise ValueError(f"duplicate calibration candidate {identity}")
        seen.add(identity)
        status = candidate.get("status")
        if status == "error":
            if not candidate.get("error"):
                raise ValueError("failed calibration candidate is missing its error")
            continue
        if status != "ok":
            raise ValueError(f"invalid calibration candidate status: {status!r}")
        samples = candidate.get("samples_us")
        if not isinstance(samples, list):
            raise ValueError("successful calibration candidate is missing raw samples")
        summary = summarize_samples(samples)
        if candidate.get("summary") != summary:
            raise ValueError("calibration candidate summary is not derived from raw samples")
        successful.append(candidate)
    if not successful:
        raise ValueError("all calibration candidates failed")
    winner = min(
        successful,
        key=lambda row: (float(row["summary"]["median_us"]), row["identity"]),
    )
    return {
        "identity": winner["identity"],
        "config": canonical_config(winner["config"]),
        "median_us": winner["summary"]["median_us"],
    }


def derive_configs(token_evidence: dict[str, Any]) -> dict[str, dict[str, int]]:
    if not token_evidence:
        raise ValueError("calibration artifact has no token evidence")
    configs: dict[str, dict[str, int]] = {}
    for token_key in sorted(token_evidence, key=int):
        if str(int(token_key)) != token_key or int(token_key) <= 0:
            raise ValueError(f"invalid token bucket key: {token_key!r}")
        row = token_evidence[token_key]
        selection = derive_token_selection(row.get("candidates", []))
        if row.get("selection") != selection:
            raise ValueError(f"token bucket {token_key} selection is not derived")
        correctness = row.get("correctness")
        if not isinstance(correctness, dict):
            raise ValueError(f"token bucket {token_key} is missing correctness evidence")
        if correctness.get("identity") != selection["identity"]:
            raise ValueError(f"token bucket {token_key} correctness checked another config")
        if correctness.get("passed") is not True:
            raise ValueError(f"token bucket {token_key} failed correctness")
        checked_tokens = correctness.get("checked_tokens")
        if (
            isinstance(checked_tokens, bool)
            or not isinstance(checked_tokens, int)
            or checked_tokens != int(token_key)
        ):
            raise ValueError(
                f"token bucket {token_key} correctness checked another token count"
            )
        for metric in ("max_abs", "relative_l2"):
            value = correctness.get(metric)
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(float(value))
                or float(value) < 0
            ):
                raise ValueError(
                    f"token bucket {token_key} has invalid correctness metric {metric}"
                )
        configs[token_key] = selection["config"]
    return configs


def validate_artifact(data: dict[str, Any]) -> dict[str, dict[str, int]]:
    if data.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("unsupported Triton MoE calibration schema")
    calibration = data.get("calibration")
    if not isinstance(calibration, dict):
        raise ValueError("generated Triton MoE config is missing calibration evidence")
    if calibration.get("derivation_version") != DERIVATION_VERSION:
        raise ValueError("stale Triton MoE calibration derivation")
    provenance = calibration.get("provenance")
    required_provenance = {
        "generator",
        "generator_source_sha256",
        "generated_at_utc",
        "gpu_name",
        "compute_capability",
        "torch_version",
        "triton_version",
    }
    if not isinstance(provenance, dict) or not required_provenance <= set(provenance):
        raise ValueError("Triton MoE calibration provenance is incomplete")
    source_hash = provenance.get("generator_source_sha256")
    if not isinstance(source_hash, str) or len(source_hash) != 64:
        raise ValueError("invalid Triton MoE generator source identity")
    for field in ("sm_major", "num_experts", "hidden_size", "intermediate_size", "top_k"):
        if (
            isinstance(data.get(field), bool)
            or not isinstance(data.get(field), int)
            or data[field] <= 0
        ):
            raise ValueError(f"invalid Triton MoE calibration field {field}")
    derived = derive_configs(calibration.get("tokens", {}))
    if data.get("configs") != derived:
        raise ValueError("Triton MoE runtime configs are not derived from calibration evidence")
    return derived


def atomic_write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        with temporary.open("w") as handle:
            json.dump(payload, handle, indent=2, sort_keys=False)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


__all__ = [
    "DERIVATION_VERSION",
    "SCHEMA_VERSION",
    "atomic_write_json",
    "canonical_config",
    "config_identity",
    "derive_configs",
    "derive_token_selection",
    "make_candidate",
    "summarize_samples",
    "validate_artifact",
]
